/**
 * The system's only icon component — a single wrapper over 233 stroke glyphs
 * drawn on a 16px grid and filled with currentColor, so an icon takes the
 * colour of the text around it.
 *
 * @startingPoint section="Foundations" subtitle="233-glyph icon set" viewport="700x300"
 */
export interface IconProps extends React.SVGProps<SVGSVGElement> {
  /** Glyph name, e.g. "IconSearch". */
  name: IconName;
  /** Rendered box in px. Defaults to 16 — the size every control expects. */
  size?: number;
}

export declare function Icon(props: IconProps): JSX.Element | null;

/** Every glyph name in the set, sorted. */
export declare const iconNames: IconName[];
